HERO_STR_STATIC(hero_str_44ccd22b, "the ownership pass produced an ill-formed program");
HERO_STR_STATIC(hero_str_308e3319, "holes");
HERO_STR_STATIC(hero_str_90c0d0b, "no binary: ");
HERO_STR_STATIC(hero_str_17aba2af, "holes produce no binary");
HERO_STR_STATIC(hero_str_da05315, "the FFI check");
