HERO_STR_STATIC(hero_str_19c5b8c4, " could not run");
HERO_STR_STATIC(hero_str_1ccc036a, " reported");
HERO_STR_STATIC(hero_str_6ea28d90, "the verifier refused");
HERO_STR_STATIC(hero_str_38b9, "no");
HERO_STR_STATIC(hero_str_1fbd1637, "clang is below the floor");
HERO_STR_STATIC(hero_str_3ec765a9, "error while emitting ");
HERO_STR_STATIC(hero_str_4376d1e5, "internal error: a group head's name was never judged\n  ");
HERO_STR_STATIC(hero_str_7fa1723e, "a group head's name reached the tools unjudged");
HERO_STR_STATIC(hero_str_2eb53ce, "no sanitizer runtime");
