HERO_STR_STATIC(hero_str_7ff3eea1, "the package could not answer");
HERO_STR_STATIC(hero_str_34aa5476, "the artifact was not written");
HERO_STR_STATIC(hero_str_eb79a2a, "error: this machine's clang has no sanitizer runtime, so `--sanitize` cannot build here: the runtime's sanitizer headers are not on clang's include path, as its words below say. Some systems ship them apart from clang, Debian and Ubuntu as `libclang-rt-<version>-dev`; install that, or build without `--sanitize`");
